// Setup: Assume addr is page-aligned
size_t length = PAGE_SIZE * 3;
void *addr = (void*)0x10000000;

// Vector must hold length / PAGE_SIZE bytes
unsigned char vec[3];

// Query residency status
int ret = mincore(addr, length, vec);

// Check result
if (ret == 0) {
    // Residency is indicated by the Least Significant Bit (0x1)
    if (vec[0] & 0x1) {
        // First page is resident (in core)
    }
    // vec[1] corresponds to the second page, etc.
} else {
    // Handle error (e.g., EFAULT, ENOMEM)
}
